  VALUES 
    (253::BIGINT, 'la verdad es que para instru está god pero ya no va a dar el curso :('::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Pocos exámenes']::TEXT[], '2026-06-02T00:00:00+00:00'::TIMESTAMPTZ, '561be05084ecf1f37acdd674f959512effb25b8ea7004773f532495b3ad52e06'::TEXT, ARRAY[4123]::BIGINT[]),
    (253::BIGINT, 'Es buena nota, cae bien'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Clases excelentes']::TEXT[], '2026-06-02T00:00:00+00:00'::TIMESTAMPTZ, '3f9370f5b6271cd2b885ea8035d4e73191bc27939e5f703b8613432d058f779d'::TEXT, ARRAY[4123]::BIGINT[]),
    (253::BIGINT, 'Voy por semana 11 y aún no he aprendido nada en el curso, el mae solo lee presentaciones mediocres y luego deja tareas que no se relacionan a los más mínimo a lo que leyó, sino que tratan de investigar en datasheets que no enseña como leer, tampoco está claro que se espera él en la tarea.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-10-07T00:00:00+00:00'::TIMESTAMPTZ, 'f2f03bbd22e2303ac46c0b38662da6f3fe89b4c39f9b167269da8f42dc8a6c7d'::TEXT, ARRAY[4121]::BIGINT[]),
    (253::BIGINT, 'La clase se basa en leer una presentación demasiado simple, los exámenes los hace una hora antes de aplicarlos y la retroalimentación llega demasiado tarde.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2024-04-07T00:00:00+00:00'::TIMESTAMPTZ, '69572200da5e24ae9e7986d58f61375967b88602025ec0372c248a774b121d3b'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'No es como se ve en Github, es todo bipolar'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-04-07T00:00:00+00:00'::TIMESTAMPTZ, '38726ee202c7c1f8dae7b5abb111232cb997ed2121d952615c51abc3c9ca3077'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'El mae es buena nota, se puede pasar un rato vacilón con él. Pero como profe, deja mucho que desear: aparte de que pasa criticando al contenido y estructura del curso (algo que se vuelve muy chocante), al mae no le importa en lo más mínimo usted, el curso o la carrera.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2023-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'a9e3d285d14ae45a2db6430c4444069c5c83bdd526abcb0ce5459274b879ccad'::TEXT, ARRAY[4121]::BIGINT[]),
    (253::BIGINT, 'Pues no tiene caso calificar bien o mal este profesor... Bueno "profesor". Él es ingeniero, no profesor y pues es el unico que da electricidad 1. Asi que...suerte. La clase no es obligatoria pero como nuuuunca usa el correo pues cualquier anuncio importante lo hace en la clase y si no vas, GG.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2023-11-23T00:00:00+00:00'::TIMESTAMPTZ, '4f5118bfaa130827ea7c262f919414277d0d515cf9bf707f5e296bae1bd7cf18'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'El peor profe que he tenido en mi vida. El mae no sabe enseñar y se excusa con la frase de "todos aprenden diferente".El mae es un vagazo. Eso si, es pura vida y ayuda. Tareas todas las semanas y el 2do examen es una vulgaridad. Engreído en consultas, desmeritando a los estudiantes de hoy en día.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2023-11-22T00:00:00+00:00'::TIMESTAMPTZ, '985169b3be0c97d196694f2304c2f526b81019dbe0806bd9f0ca2d5e403ae5c7'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'El profesor en serio es una persona muy agradable y dispuesto ayudar. Pero le falta mejores habilidades para enseñar y que coincida con lo que evalúa. Porque en los exámenes siempre encuentra la manera de poner algo que no tenga nada que ver con lo que enseña o aparezca en otro lugar.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2023-11-05T00:00:00+00:00'::TIMESTAMPTZ, 'd8ad8f04d5b42b442e4ddf2fa0a2c7b06a48dd66226dd7ca00b2de18ec308291'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'El profe es buena nota y relajado, pero al momento de explicar sencillamente no se le entiende y mas bien confunde, recomiendo asistir a tutorias y estudiar con el libro, es la unica forma de pasar. Busque buen grupo para las tareas. No hace quiz pero si hay tareas todas las semanas.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, '847d2f0aeb4165ec78737af787cff1e9e4fea81541ba36b579a7bb1ff47adfc1'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'Por más que intente ser bueno el mae simplemente no la da, no tiene vocación, le hace falta mucho como profesor. Va a necesitar mucho estudio propio porque con las explicaciones que da no es suficiente, los exámenes suelen ser de conocimiento básico de los temas, nada muy volado.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-18T00:00:00+00:00'::TIMESTAMPTZ, '3103d310295404f78810132cdf15faf67d1d895d9db4dd3887326ff7c1949f12'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'El profe puede mejorar muchísimo en la forma en que califica los exámenes. Solamente revisa la respuesta, no se toma el tiempo de revisar el procedimiento del estudiante. Así que presten mucha atención en los exámenes, un signo o un mal despeje convierten un 100 en un 70, sin exagerar'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-15T00:00:00+00:00'::TIMESTAMPTZ, '99316f115d55e77b249beab3e5cec5e4e08c70df51a2202932796e48491b9d91'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'El contenido de una clase se sustituye por un video viejo de 20min de poca profundidad. Las clases presenciales son como una hora de consulta masiva. De este profe no depende que usted pase o se quede, si logró aprender por su cuenta bien y si no pues F. Vayan a tutorías con Mariana Solís.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2022-10-21T00:00:00+00:00'::TIMESTAMPTZ, 'eeeeb53cf08de2e01e53ae40c627418e3d5781e7af5b628e5099d1e74b914b5d'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'Explica bien y deja tareas todas las semanas, no es un mal profe pero podría ser mejor, los examenes que deja a veces son de los semestres pasados o similares, al final del curso como no hay repo pasa con 60.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2022-06-20T00:00:00+00:00'::TIMESTAMPTZ, '7e75b3cc8168856fda5401fbfd3cb7040d10f07cce9ccc444644a8cf820fe96c'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'No sé porqué le dan tan malas calificaciones, el curso en sí es difícil a huevos va a tener que estudiar bastante, pero el profe es muy pura vida y al final del curso si usted fue a las clases y a consulta él hace curva. Y en el lab se pasa bastante fácil.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo']::TEXT[], '2022-06-18T00:00:00+00:00'::TIMESTAMPTZ, '33d0d5295bd7e3645c3fbaa12477265223aba4821a541734abb17bcd0c4a40bb'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'En el lab de electri mándese con él sin miedo, es super relajado, explica bastante bien y hace la clase llevadera. A veces se va del aula y uno se queda solo pero ya al rato llega. Los informes los califica muy suave.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'ade7b2eb2a03f424d3893d4948b4af5b63d0200583b0738d69e8877b8c9e7900'::TEXT, ARRAY[925]::BIGINT[]),
    (253::BIGINT, 'El profe como tal es bueno, pero el curso está mal planteado, la evaluación se basa en 6 prácticas y 6 tareas únicamente, por lo que cada error baja muchos puntos, además de ello el asistente tarda bastante en dar las notas y casi no hay retroalientación'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Pocos exámenes', 'Aspectos de calificación claros']::TEXT[], '2022-06-11T00:00:00+00:00'::TIMESTAMPTZ, '66c2debdb566052d757a0d1d78ebb5a2b03691d2097fe9f1dc3db14472fde271'::TEXT, ARRAY[4123]::BIGINT[]),
    (253::BIGINT, 'El profe es pura vida, aclara dudas y no me parece que explique mal; pienso que debería tener una mejor nota. Tener mucho cuidado con los formatos de las respuestas en los exámenes, porque lo toma muy en cuenta a pesar que la respuesta esté correcta (virtual).'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2022-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'ef734d7d44499d5b5cf5026e168a26d35b0787eb8aa1be2902b7403022b9b0ba'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Aspectos de calificación claros']::TEXT[], '2022-05-23T00:00:00+00:00'::TIMESTAMPTZ, '6cda0496bb07da9bba699a81440585e37a29fe9392257abeddc22f5f6c56392b'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'En el lab es super relax, explica bien y está siempre dispuesto en ayudar, dele sin miedo con este profe, recomendadísimo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'a42d8ecc0bc89ba3117015b4d224bb54197c3de0cdd51d18070f560768b054a7'::TEXT, ARRAY[925]::BIGINT[]),
    (253::BIGINT, 'Muy buena clase, el profe hace lo posible para que sea buena la clase con la virtualidad. Las clases son muy cortas y el profe si responde las dudas.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2022-01-18T00:00:00+00:00'::TIMESTAMPTZ, '607045636d9bc67b3e8f03f05855b258f2f3208c728aef8c30ba7154b0e406f6'::TEXT, ARRAY[925]::BIGINT[]),
    (253::BIGINT, 'En sí el curso se pasa viendo los videos del canal de él y también con el libro de consulta. El profe usa las clases para hacer ejercicios, por lo que usted tiene que ir estudiado antes de la clase. El profe en sí es tuanis y explica bastante bien'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2021-12-10T00:00:00+00:00'::TIMESTAMPTZ, '67259e5bfddd4f451028fe99922942cb72b53be59a7ab4627d4ef589ce47062b'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'Este semestre inició con la cola entre las patas después de la cagada que se pego el semestre pasado, sin embargo, las clases son inútiles no sirven para nada, para los exámenes tiene un sistema super estúpido por carnet, el 2do examen lo tira a matar y solo sabe enredar, al menos es buena gente'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-05T00:00:00+00:00'::TIMESTAMPTZ, '2a2c849345bc818c2f5d85bf6ff689121b1125339e5e071f5ca69fc944972496'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Exámenes retadores']::TEXT[], '2021-11-27T00:00:00+00:00'::TIMESTAMPTZ, '39fc14f6202e15d10cbfc56eed21be366101c4dd6d3a26fd05fdc03628add49c'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'El profe es muy comprensivo, pero las clases teóricas son irrelevantes con las prácticas. Por lo demás, un buen profe, usted siente que es compañero suyo.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2021-11-27T00:00:00+00:00'::TIMESTAMPTZ, '8fea0f244c9200cf824e92a7aa63b114f57fbb6017ef90de343aae04e9ecf668'::TEXT, ARRAY[4121]::BIGINT[]),
    (253::BIGINT, 'Es pésimo, no ayuda en nada, los examenes son las peores evaluaciones del mundo porque solo califica respuestas y no toma en cuenta los procedimientos, en el segundo parcial lo pone para que todo mundo se quede.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-25T00:00:00+00:00'::TIMESTAMPTZ, '769f06d2cc3988f7afa52a2349eb2d8ef224d2961716d2b3d2e1acabc664ac32'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'Dice lo que se hara antes de la clase rapido y luego lo deja a uno solo, hay que ir preparado y se usan varios software de simulacion, por lo que saque el rato para aprender como funcionan a fondo porque el explica muy por encima lo que hay que hacer'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2021-11-23T00:00:00+00:00'::TIMESTAMPTZ, '134ddd96f59561ec7a8b37a470a338ad0e396ddb2f88067a44ad5b8c741e87aa'::TEXT, ARRAY[925, 994]::BIGINT[]),
    (253::BIGINT, 'El profe es excelente persona y ayuda demasiado con cualquier duda, pero explica demasiado rápido en clases y sus evaluaciones son de MUY alto nivel. Ordenado-complica mucho el curso.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2021-11-09T00:00:00+00:00'::TIMESTAMPTZ, 'b31c3a494ce2dc3b858ac995104cfb23beec2f7486bda28e3c2b1a5252354ba9'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'el mae es todo guapo jaja, pero explica demasiado mal y preparasen en python, necesita programar en electri 1 y lab 1'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-08-11T00:00:00+00:00'::TIMESTAMPTZ, '35ec5744547c586460bfecdadcc3a85e033fc473a2490322cab500098ad4d970'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'Es demasiado desordenado, perfectamente puede dar indicaciones de un asignacion y dias depues enviar un correo con indicaciones totalmente diferentes y confusas, en el inicio del semestre pasado inicio dando temas de semana 4 y se dio cuenta y por cuenta propia estudiar semana 1,2,3 solos, PÉSIMO'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, '70d54036b210e113b701797ac7741a86dc0820a82effde732497c040962c9b4e'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2021-07-03T00:00:00+00:00'::TIMESTAMPTZ, 'a10876b33a2ede0038bdf118b49d7364fff58e6cebb1c39a1c6db9be5297130f'::TEXT, ARRAY[925, 994]::BIGINT[]),
    (253::BIGINT, 'El mae es pura vida pero no da la clase, solo consulta, a si que vaya preparado, deja tareas dificiles y confusas para la cuales si o si tiene que saber programar en python, y los examenes utiliza el mismo formato de los semestres pasados por lo que use los viejos para estudiar, lo va a sufrir'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-07-01T00:00:00+00:00'::TIMESTAMPTZ, '8eba14ae46b6bc0d00cf1b359e33ad8ac9c1f261ef3fba36df2a08e06a655b75'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'Debe saber python muchísimo para las tareas. El profe es buena nota, pero usted debe ir a la clase estudiado porque él sólo atiende consultas. Déjelo como una segunda opción por aquello.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2021-06-23T00:00:00+00:00'::TIMESTAMPTZ, '25b29b326b3a663aa8bff61477f95a6d09fdf8d5f3bc4bb200166fff22ec2ec2'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'Explica muy poco y medio confuso. Los informes y los trabajos previos los califica suave pero los examenes si los califica duro.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'a8eed6fbc76db103b56e488f052988de0c1d24a7789537a00ef23508a75e080b'::TEXT, ARRAY[925]::BIGINT[]),
    (253::BIGINT, 'El profe deja tareas nada relacionadas al curos, son puro codigo (python), no da clase, solo consulta, no tiene clases preparadas, solo espera a que uno pregunte y si no las hay simplemente apaga la clase. En los examenes se la rifa para caer mal, simplemente no matricule con él si no quiere joderse'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-05-19T00:00:00+00:00'::TIMESTAMPTZ, 'ae61a0c4920d38cc587aac56db0d326e3e745f586a6620f242e77484cfb2eaa6'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'El curso no es sencillo, hace los examenes de alto nivel. Si uno le pide ayuda el se toma el tiempo para explicar. Un aspecto bueno y a la vez dificil es que deja trabajos de programación, simulación matemática y otros temas variados, la mayoría de estas temas son MUY ÚTILES!!'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Da crédito extra', 'Exámenes retadores']::TEXT[], '2021-03-11T00:00:00+00:00'::TIMESTAMPTZ, '6017b2505b1dfc046cd83b342e0293196da0cf451927c4dba7b3e3766a1f6f80'::TEXT, ARRAY[925]::BIGINT[]),
    (253::BIGINT, 'El tipo no da clases, agarra las horas de clase para dar consulta. Deja tareas LARGAS en las que hay que programar mucho y no tienen mucho que ver con la materia del curso en sí.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2021-02-17T00:00:00+00:00'::TIMESTAMPTZ, 'ad2734df7b1f085ab9426a862d4547b29e872850d707ef4dc61b2e52912977b0'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'Es excelente profesional y trata de que uno profundize áreas más allá del curso, pero como lo usual en el TEC la didáctica es mala.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Exámenes retadores']::TEXT[], '2021-02-12T00:00:00+00:00'::TIMESTAMPTZ, '5cb58fa90ef40206a2af39ae8ab35ef23a1063645f237d96f008eb6a8a247c38'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'Las tareas que deja son 0 relacionadas al curso, usualmente las tareas te preparan para el examen, pero en este caso no, son mas como tareas de código'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2020-09-17T00:00:00+00:00'::TIMESTAMPTZ, '0c685dab1e3261e6f64b4e6d65431a2d816d62ddda5e35006bbe01b6832b2309'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'Muy pura vida. Al final regaló el curso porque estaba ocupado con otras cosas, pero no califica duro y es muy fácil.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muy cómico']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '8e05bfadfdde72efbfc829063ad5425db684580f02a8283d84593acd5567ffdb'::TEXT, ARRAY[1835]::BIGINT[]),
    (253::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2016-08-03T00:00:00+00:00'::TIMESTAMPTZ, '41c48e71fe3e641df710f3f108d3e7c005a9ef469b5ab9df703d6bfa615d9f3c'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'Lo único bueno de el es que se va para japón'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'b8a847aa9324b9e08e2d220fee13e34bfb6cebd89c3a6c24eeee5da292b61f4f'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'tares y proyectos grupales, calificación binaria, hay que practicar bastante, en consulta saca las dudas, no es un mal profe, le cuadra ir mejorando la manera de dar la clase'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2016-01-31T00:00:00+00:00'::TIMESTAMPTZ, '7386327cb819da1c6531880585764ed8bedf7c6f6e9f7c3f225754f508d6ce62'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'El que le pone pasa, explica lo necesario.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-12T00:00:00+00:00'::TIMESTAMPTZ, 'd2d89cfe9fecbe6006ad0dcf9b6c13391b5160a4f1257598412333f1ab4395ba'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'Uno de los peor profes del TEC, intente no meter nada con él y si solo él da el curso, resignese. Evalúe el tiempo para aprender solo que uno necesita si matricula con él. Es buena persona, en especial con las mujeres'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('5','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-10T00:00:00+00:00'::TIMESTAMPTZ, '4e1ebe6a8ea5f24cb91bd16a80011bcb04f0989c3975f68c14f46fafb449ce85'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'Explica lo basico, hace muchos ejemplos y aclara dudas las veces que sea necesario. Califica practicamente binario'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'bb8a33752dfce99d483104d43fe00128f33956759e0c21057d853ff9bdc71aee'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'Explica masomenos, lo mejor es ir a la clase y ese mismo día estudiar para sacar dudas y aclararlas, en 2sem-15 empezó a hacer los examenes relativamente fáciles pero califica binario, bueno o malo(no da revisa para nada procedimiento, sólo respuesta) lo mejor es ponerle bastante desde el inicio'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-26T00:00:00+00:00'::TIMESTAMPTZ, '43991af35d46254923e573d305e370f8bc63aef2461ad5d98c5de40311e1be5e'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'Cuesta mucho entender en clase. Califica casi binario y es bastante rufo. Las clases son divertidas mientras esté de buenas.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-18T00:00:00+00:00'::TIMESTAMPTZ, '40aefe0e98c574129d8c7cc5ea15c94b37418cec7f19aaea3fa5622f1bc63b33'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-29T00:00:00+00:00'::TIMESTAMPTZ, '82586aa8dc92f5e6082cc74126ab82cb3ee51c669a5f60d1b4f48d5b81d26e37'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'Explica pésimo piensa que uno ya va a clases con las cosas aprendidas, si uno le pregunta algo no sabe como responderle y le hace más enredo, no sabe enseñar y no le importa que usted aprenda, para nada recomendado.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-28T00:00:00+00:00'::TIMESTAMPTZ, '91f504ea7153a11bb10afe3a18434167d9ce26e0acd890b3a61d686d608823df'::TEXT, ARRAY[610]::BIGINT[]),
    (253::BIGINT, 'Explica pésimo y es un asco calificando. Hace los exámenes demasiado difíciles para lo que explica'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-11T00:00:00+00:00'::TIMESTAMPTZ, '577247e76d38e3ddc93bc60123d9bb39aad11818455979ecd54653b2a4937621'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'muy tuanis como persona, pero lo culea a uno en los examenes!!'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-06T00:00:00+00:00'::TIMESTAMPTZ, '5b6ac801282e39ce292a4e2f886484600a283a57db69cb1cddb8f5fef7261299'::TEXT, ARRAY[926]::BIGINT[]),
    (253::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-05T00:00:00+00:00'::TIMESTAMPTZ, '21fc71269ecd4c2f20fd4a6ca8e2241c0d9d9158375abf4cf3ae74fcde32c573'::TEXT, ARRAY[610]::BIGINT[]),
    (253::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-05T00:00:00+00:00'::TIMESTAMPTZ, '2b616cf1eb1d4ef084282692c6802b8dd2c4e9ce28ad59191453f970c2d1ef21'::TEXT, ARRAY[610]::BIGINT[]),
    (253::BIGINT, 'No explica nada para después llegar a aplastar a la gente en las pruebas'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-31T00:00:00+00:00'::TIMESTAMPTZ, '3587a4669293d86345ca23cd60da38e46ac30fa2e541d16855feb1e393f9dea6'::TEXT, ARRAY[926]::BIGINT[]),
